"""The third-party notices the desktop app ships (#63): what they are made from, and what they refuse."""

from __future__ import annotations

import json
from pathlib import Path

import pytest

from scripts import third_party_notices as notices

LOCK = """\
# This file was autogenerated by uv via the following command:
#    make lock
alembic==1.20.1 \\
    --hash=sha256:aaaa \\
    --hash=sha256:bbbb
    # via -r requirements.in
colorama==0.4.6 ; sys_platform == 'win32' \\
    --hash=sha256:cccc
pydantic-core==2.50.2 \\
    --hash=sha256:dddd
uvloop==0.23.0 ; platform_python_implementation != 'PyPy' \\
    --hash=sha256:eeee
"""

SPEC = """\
a = Analysis(
    ["entry.py"],
    pathex=[ROOT],
    excludes=["uvicorn", "uvloop", "tkinter"],
    noarchive=False,
)
"""


def test_the_runtime_set_is_what_the_lock_installs_here_less_what_the_spec_leaves_out():
    on_windows = {"sys_platform": "win32", "platform_python_implementation": "CPython"}
    on_a_mac = {"sys_platform": "darwin", "platform_python_implementation": "CPython"}
    assert notices.runtime_names(LOCK, on_windows) == ["alembic", "colorama", "pydantic-core", "uvloop"]
    assert notices.runtime_names(LOCK, on_a_mac) == ["alembic", "pydantic-core", "uvloop"]
    assert notices.not_frozen(SPEC) == {"uvicorn", "uvloop", "tkinter"}
    left = notices.not_frozen(SPEC)
    assert [n for n in notices.runtime_names(LOCK, on_a_mac) if n not in left] == ["alembic", "pydantic-core"]


def test_a_spec_with_no_excludes_is_refused_rather_than_read_as_none():
    with pytest.raises(SystemExit, match="Analysis"):
        notices.not_frozen("a = 1\n")


def _package(root: Path, name: str, version: str, licence: str | None, text: str | None) -> dict:
    folder = root / "node_modules" / name
    folder.mkdir(parents=True)
    (folder / "package.json").write_text(json.dumps({"name": name, "version": version}))
    if text is not None:
        (folder / "LICENSE").write_text(text)
    return {"name": name, "version": version, "path": str(folder)}


def test_the_node_section_names_each_bundled_package_with_its_licence_text(tmp_path: Path):
    react = _package(tmp_path, "react", "19.3.1", "MIT", "MIT License\n\nCopyright (c) Meta")
    tiny = _package(tmp_path, "tiny", "1.0.0", "ISC", None)
    known = {
        "react@19.3.1": {"licenses": "MIT", "repository": "https://github.com/facebook/react", "licenseFile": str(tmp_path / "node_modules/react/LICENSE")},
        "tiny@1.0.0": {"licenses": "ISC", "repository": ""},
        "unbundled@2.0.0": {"licenses": "MIT"},
    }
    text = notices.node_section([react, tiny], known)
    assert "react 19.3.1  --  MIT\nhttps://github.com/facebook/react\n" in text
    assert "Copyright (c) Meta" in text
    assert "tiny 1.0.0  --  ISC\n" in text
    assert "carries no licence file" in text
    assert "unbundled" not in text


def test_a_bundled_package_the_checker_does_not_know_or_cannot_license_stops_the_build(tmp_path: Path):
    react = _package(tmp_path, "react", "19.3.1", "MIT", "MIT")
    with pytest.raises(SystemExit, match="react@19.3.1 was bundled"):
        notices.node_section([react], {})
    with pytest.raises(SystemExit, match="no licence found"):
        notices.node_section([react], {"react@19.3.1": {"licenses": "UNKNOWN"}})


def test_the_python_section_carries_the_licence_text_pip_licenses_read():
    found = [
        {"Name": "alembic", "Version": "1.20.1", "License": "MIT", "URL": "https://alembic.sqlalchemy.org", "LicenseText": "Copyright Michael Bayer"},
        {"Name": "argon2-cffi", "Version": "25.1.0", "License": "MIT", "URL": "", "LicenseText": ""},
    ]
    text = notices.python_section(found)
    assert text.startswith("alembic 1.20.1  --  MIT\nhttps://alembic.sqlalchemy.org\n")
    assert "Copyright Michael Bayer" in text
    assert "argon2-cffi 25.1.0  --  MIT\n-" in text


def test_the_whole_text_has_its_three_sections_and_refuses_an_empty_one():
    text = notices.render("0.15.0", "alembic 1.20.1  --  MIT\n", "react 19.3.1  --  MIT\n", "electron 45.2.1  --  MIT\n")
    assert text.startswith("Household Spend Tracker 0.15.0: third-party notices\n")
    assert text.index("The backend (Python)") < text.index("alembic 1.20.1") < text.index("The web client (JavaScript)")
    assert text.index("react 19.3.1") < text.index("The desktop shell (JavaScript, Electron)") < text.index("electron 45.2.1")
    with pytest.raises(SystemExit, match="client section would be empty"):
        notices.render("0.15.0", "alembic 1.20.1  --  MIT\n", "  \n", "electron 45.2.1  --  MIT\n")


def test_the_check_refuses_a_missing_empty_or_stale_file(tmp_path: Path, monkeypatch: pytest.MonkeyPatch):
    monkeypatch.setattr(notices, "NOTICES", tmp_path / "THIRD-PARTY-NOTICES.txt")
    monkeypatch.setattr(notices, "CHROMIUM", tmp_path / "LICENSES.chromium.html")
    monkeypatch.setattr(notices, "app_version", lambda: "0.15.0")
    with pytest.raises(SystemExit, match="missing or empty"):
        notices.check()
    (tmp_path / "LICENSES.chromium.html").write_text("<html>")
    (tmp_path / "THIRD-PARTY-NOTICES.txt").write_text("")
    with pytest.raises(SystemExit, match="missing or empty"):
        notices.check()
    (tmp_path / "THIRD-PARTY-NOTICES.txt").write_text(notices.render("0.14.1", "a", "b", "c"))
    with pytest.raises(SystemExit, match="another version"):
        notices.check()
    (tmp_path / "THIRD-PARTY-NOTICES.txt").write_text("Household Spend Tracker 0.15.0: third-party notices\nThe backend (Python)\n")
    with pytest.raises(SystemExit, match="no section 'The web client"):
        notices.check()
    (tmp_path / "THIRD-PARTY-NOTICES.txt").write_text(notices.render("0.15.0", "a", "b", "c"))
    notices.check()
